	L["good.core.crest.fish.6289.description"] = "Ein Schnapper, ganz Kiefer, auf Teichgrün. Biss um Biss verdient."
	L["good.core.crest.fish.6289.name"] = "Wappen: {fish}"
	L["good.core.crest.fish.6291.description"] = "Der kleinste Fisch auf jedem Schild, und der, mit dem man am schwersten aufhört."
	L["good.core.crest.fish.6291.name"] = "Wappen: {fish}"
	L["good.core.crest.fish.6299.description"] = "Ein trauriger grauer Fisch auf dunklem Wasser. Jemand musste sie alle sammeln. Das warst du."
