	L["good.core.crest.fish.6317.name"] = "Wappen: {fish}"
	L["good.core.crest.fish.6358.description"] = "Ein öliger Lachs auf Blau, glänzend. Jede Farbe, die das Öl hervorbringen konnte, ist verbucht."
	L["good.core.crest.fish.6358.name"] = "Wappen: {fish}"
	L["good.core.crest.fish.6359.description"] = "Ein roter Schnapper, der durch warmes Wasser aufsteigt, für den Angler, der ihn in jeder seiner Farben gesehen hat."
	L["good.core.crest.fish.6359.name"] = "Wappen: {fish}"
	L["good.core.crest.fish.6361.description"] = "Ein Thunfisch mit weit gespreizten Regenbogenflossen, Farben, die auf einem Schild nie verblassen."
