	L["good.core.crest.fish.6362.description"] = "Ein gesprenkelter Kabeljau auf tiefem Blau, stur wie die Felsen, zwischen denen er sich versteckt."
	L["good.core.crest.fish.6362.name"] = "Wappen: {fish}"
	L["good.core.crest.fish.6458.description"] = "Ein kleiner Fisch auf trübem Wasser, so sauber, wie er je sein wird."
	L["good.core.crest.fish.6458.name"] = "Wappen: {fish}"
	L["good.core.crest.fish.6522.description"] = "Etwas mit zu vielen Augen auf einem Feld aus schlechtem Wasser. Beweis für einen starken Magen."
	L["good.core.crest.fish.6522.name"] = "Wappen: {fish}"
	L["good.core.crest.fish.8365.description"] = "Eine Forelle mit glänzendem Kopf, auf Flussgrün. Der Schmied hat aufgehört zu fragen."
	L["good.core.crest.fish.8365.name"] = "Wappen: {fish}"
	L["good.core.crest.plain.description"] = "Kein Wappen, nur der Name des Besitzers. Viele gute Angler wollten nie mehr."
	L["good.core.crest.plain.name"] = "Schlicht"
	L["good.core.newssign.astro.description"] = "Ein Stern fällt, und ein Messing-Astrolabium dreht sich um ihn auf, bis seine Scheibe sich zum Nachthimmel öffnet. Bei Sternenlicht liest sich die Nachricht besser."
