	L["good.core.newssign.coral.description"] = "Ein Tropfen fällt, und aus dem Spritzer taucht eine perlengesäumte Tafel auf, umwachsen von Tang und Koralle. Blasen steigen. Dort unten liest jemand mit."
	L["good.core.newssign.coral.name"] = "Koralle"
	L["good.core.newssign.kraken.description"] = "Zwei Tentakel bringen eine algenbehangene Steintafel herab und packen sie an den Ecken. Sie tropft. Die Saugnäpfe pulsieren. Wo der Rest ist, fragt keiner."
	L["good.core.newssign.kraken.name"] = "Krake"
	L["good.core.newssign.lantern.description"] = "Eine Messinglaterne, an einer Kette vor eine dunkle Scheibe gesenkt. Sie entflammt, die Zeilen erscheinen nacheinander, und die Glühwürmchen bleiben."
	L["good.core.newssign.lantern.name"] = "Laterne"
	L["good.core.newssign.scroll.description"] = "Eine gerollte Karte, hinter einem rot-weißen Schwimmer herabgespult. Sie entrollt sich mit der Nachricht und nimmt noch ein Wachssiegel mit."
	L["good.core.newssign.scroll.name"] = "Schriftrolle"
	L["good.core.newssign.wood.description"] = "Verwitterte Planken an zwei Seilen. Es fällt, schwingt, kommt zur Ruhe und sagt, was es zu sagen hat. Schlicht, und stolz darauf."
	L["good.core.newssign.wood.name"] = "Holz"
	L["good.core.soundset.arcade.description"] = "Münzpiepsen und eine Siegesmelodie vom Automaten hinten in der Taverne. Einen Fisch einwerfen, um fortzufahren."
	L["good.core.soundset.arcade.name"] = "Spielautomat"
	L["good.core.soundset.boing.description"] = "Eine Feder, ein Klatschen und ein Platschen, in welcher Reihenfolge der Fisch auch will. Niemand kommt zu Schaden."
	L["good.core.soundset.boing.name"] = "Boing!"
	L["good.core.soundset.bubbleworks.description"] = "Große runde Blasen, die aus der Tiefe aufsteigen, und irgendwo weit draußen sagt ein sehr freundlicher Wal Hallo."
	L["good.core.soundset.bubbleworks.name"] = "Blasenwerk"
	L["good.core.soundset.dragonroost.description"] = "Ein Drache auf einem hohen Sims, Flügelschlagen, und ein Horn antwortet auf sein Brüllen. Der Fisch war es wert, ihn zu wecken."
	L["good.core.soundset.dragonroost.name"] = "Drachenhorst"
	L["good.core.soundset.driftwood.description"] = "Sanftes Klopfen von Holz, wie ein Rumpf, der gegen den Steg stößt."
	L["good.core.soundset.driftwood.name"] = "Treibholz"
	L["good.core.soundset.dulcimer.description"] = "Ein Hackbrett aus der Ecke einer Hafentaverne, schnell und hell angeschlagen."
	L["good.core.soundset.dulcimer.name"] = "Tavernen-Hackbrett"
	L["good.core.soundset.frost.description"] = "Eiszapfen, die im kalten Wind aneinanderklingen und noch lange nachklingen, wenn sie längst stillhängen."
	L["good.core.soundset.frost.name"] = "Frostwindspiel"
	L["good.core.soundset.gilded.description"] = "Kleine, helle Glöckchen. Etwas zu feierlich für eine Makrele, und doch kein bisschen fehl am Platz."
	L["good.core.soundset.gilded.name"] = "Vergoldet"
	L["good.core.soundset.gizmo.description"] = "Uhrwerkticken, eine Feder, die nachgibt, und zwei fröhliche Pieptöne. Er funktioniert ziemlich sicher."
	L["good.core.soundset.gizmo.name"] = "Gnomischer Apparat"
	L["good.core.soundset.glass.description"] = "Grüne Glasschwimmer, die in einem Netz aneinanderstoßen, und Blasen, die an ihnen vorbeisteigen."
	L["good.core.soundset.glass.name"] = "Glasschwimmer"
	L["good.core.soundset.goblintill.description"] = "Die Registrierkasse eines Goblins schlägt an wie ein Hauptgewinn, überall Münzen, und der Besitzer lacht darüber. Kein Umtausch."
	L["good.core.soundset.goblintill.name"] = "Goblinkasse"
	L["good.core.soundset.harp.description"] = "Eine Harfe auf einer Waldlichtung, ein kurzer Strich über die Saiten, und die Blätter antworten."
	L["good.core.soundset.harp.name"] = "Harfe der Lichtung"
	L["good.core.soundset.kalimba.description"] = "Ein Daumenklavier an fließendem Wasser, zwei Töne und ein leises Schnarren, als hätte der Bach sie gezupft."
	L["good.core.soundset.kalimba.name"] = "Kalimba-Bach"
	L["good.core.soundset.kazoo.description"] = "Ein Kazoo, eine Lotusflöte und eine Partytröte ziehen durch den Hafen, als wäre Feiertag. Jetzt ist einer."
	L["good.core.soundset.kazoo.name"] = "Kazoo-Parade"
	L["good.core.soundset.laser.description"] = "Ein Gnomengerät, das zischt, wackelt und summt und mit einem fröhlichen Ding endet. Keine Waffe, vermutlich."
	L["good.core.soundset.laser.name"] = "Gnomischer Laser"
	L["good.core.soundset.marimba.description"] = "Warme Holzstäbe, rasch die Tonleiter hinaufgerollt wie eine auflaufende Welle."
	L["good.core.soundset.marimba.name"] = "Marimba-Ufer"
	L["good.core.soundset.mrglglgl.description"] = "Ein Murloc hat deinen Fang entdeckt und hat eine Meinung dazu. Mrgl! Mrglglgl!"
	L["good.core.soundset.mrglglgl.name"] = "Mrglglgl"
	L["good.core.soundset.musicbox.description"] = "Eine winzige Aufziehmelodie aus einer Dose mit einem Fisch auf dem Deckel. Zwei Drehungen am Schlüssel, nicht mehr."
	L["good.core.soundset.musicbox.name"] = "Spieldose"
	L["good.core.soundset.parrot.description"] = "Ein Papagei vom Hafen, eine Schiffskanone und eine Glocke. Der Papagei verkündet, die Piraten jubeln."
	L["good.core.soundset.parrot.name"] = "Piratenpapagei"
	L["good.core.soundset.rain.description"] = "Tropfen, die einer nach dem anderen auf stilles Wasser fallen, und dahinter das leise Rauschen des Regens."
	L["good.core.soundset.rain.name"] = "Regen auf dem See"
	L["good.core.soundset.shipbell.description"] = "Die Messingglocke am Mast, für den Fang geläutet, und darunter knarren Tau und Planken."
	L["good.core.soundset.shipbell.name"] = "Schiffsglocke"
	L["good.core.soundset.silithid.description"] = "Ein Schwarm Silithidenwespen schwirrt an deinem Fang vorbei, klickend und kreischend. Finger im Boot lassen."
	L["good.core.soundset.silithid.name"] = "Silithidenschwarm"
	L["good.core.soundset.slime.description"] = "Etwas Grünes, Wabbeliges freut sich über deinen Fang und schmatzt zustimmend."
	L["good.core.soundset.slime.name"] = "Schleimzeit"
	L["good.core.soundset.squeaky.description"] = "Eine Gummiente mit großen Ansichten über deinen Fang. Zweimal quietschen, einmal platschen, keine Reue."
	L["good.core.soundset.squeaky.name"] = "Quietschig"
	L["good.core.soundset.steelpan.description"] = "Helle Steeldrums aus einer warmen Lagune, zwei Töne, die klingen, als wäre die Flut auf deiner Seite."
	L["good.core.soundset.steelpan.name"] = "Steeldrum-Lagune"
	L["good.core.soundset.succubus.description"] = "Eine Sukkubus im Gebälk, schnurrend und kichernd über deinen Fang. Sag es niemandem."
	L["good.core.soundset.succubus.name"] = "Flüstern der Sukkubus"
	L["good.core.soundset.wardrums.description"] = "Tiefe Trommeln und ein dunkles Horn aus den Hügeln: ein Fang, verkündet wie der Beginn eines Marsches."
	L["good.core.soundset.wardrums.name"] = "Kriegstrommeln"
	L["good.core.toaststyle.arcane.description"] = "Eingeschrieben in einer schwebenden Stadt violetter Türme, von einem Magier, der wissen wollte, ob man einen Fisch beschwören kann. Man kann. Der Fisch war nicht erfreut."
	L["good.core.toaststyle.arcane.name"] = "Arkanes Siegel"
	L["good.core.toaststyle.birch.description"] = "Auf einen Streifen geschälter Rinde geschrieben und mit Bindfaden verschnürt. Die Tinte zieht ein und bleibt."
	L["good.core.toaststyle.birch.name"] = "Birkenrolle"
	L["good.core.toaststyle.bottle.description"] = "Aufgerollt, verkorkt und der Flut übergeben. Sie kam mit einem besseren Fang zurück, als sie mitgenommen hatte."
	L["good.core.toaststyle.bottle.name"] = "Treibglasflasche"
	L["good.core.toaststyle.chart.description"] = "Aus einer Karte gerissen, die niemand hätte verkaufen dürfen. Lotungen, Kurslinien und eine Windrose, die noch immer nach Norden zeigt."
	L["good.core.toaststyle.chart.name"] = "Seekarte"
	L["good.core.toaststyle.foil.description"] = "Die seltene, beim ersten Versuch aus dem Päckchen gezogen. Halte sie ins Licht, und der ganze See fließt hindurch."
	L["good.core.toaststyle.foil.name"] = "Glanzfolie"
	L["good.core.toaststyle.folio.description"] = "Blattgold, Lapislazuli und Zinnober, auf Pergament gelegt von einem Schreiber mit zu viel Zeit und zu wenig Fisch."
	L["good.core.toaststyle.folio.name"] = "Illuminiertes Folio"
	L["good.core.toaststyle.frost.description"] = "Über Nacht auf dem Eis liegen gelassen. Der Raureif wuchs von den Ecken herein, als die Tinte noch nass war."
	L["good.core.toaststyle.frost.name"] = "Frostbiss"
	L["good.core.toaststyle.glacier.description"] = "Geschnitten aus dem blauen Herzen eines Gletschers, älter als das erste Boot, wo die Kälte ganz hindurchgeht und das Licht verwandelt auf der anderen Seite austritt."
	L["good.core.toaststyle.glacier.name"] = "Gletscherherz"
	L["good.core.toaststyle.goblin.description"] = "Gedruckt auf einem Ticker, der nie stillsteht. Die Nieten sind tragend. Niemand weiß, was das Zahnrad tut."
	L["good.core.toaststyle.goblin.name"] = "Goblin-Ticker"
	L["good.core.toaststyle.hive.description"] = "Abgestreift von etwas Großem, das unter den Dünen lebt und heraufkommt, wenn der Sand singt. Die Platten summen noch; die Augen wachen noch."
	L["good.core.toaststyle.hive.name"] = "Schwarmchitin"
	L["good.core.toaststyle.kelp.description"] = "Ein Rücken, in Tang gewickelt und mit Perlen besetzt, die Seite glänzend wie das Innere einer Muschel."
	L["good.core.toaststyle.kelp.name"] = "Tang & Perle"
	L["good.core.toaststyle.lanternglow.description"] = "Eine warme Lampe, die hinter jedem Fang leuchtet, für Angler, die bis nach Einbruch der Dunkelheit draußen bleiben."
	L["good.core.toaststyle.lanternglow.name"] = "Laternenschein"
	L["good.core.toaststyle.leaf.description"] = "Ein großes Blatt, flach gepresst zwischen zwei schweren Büchern und golden getrocknet. Die Adern ziehen die Linien."
	L["good.core.toaststyle.leaf.name"] = "Gepresstes Blatt"
	L["good.core.toaststyle.magma.description"] = "Aus einem Fluss geschmolzenen Gesteins geschöpft, von jemandem, der die Pfanne vergessen hatte. Die Kruste kühlt ab; der Fang nicht. Nicht anfassen."
	L["good.core.toaststyle.magma.name"] = "Magmastrom"
	L["good.core.toaststyle.moon.description"] = "Nachtblaues Pergament, mit Silber beschrieben, für die Fänge, die nach den Laternen hereinkommen."
	L["good.core.toaststyle.moon.name"] = "Mondpergament"
	L["good.core.toaststyle.ooze.description"] = "Etwas kroch aus dem Sumpf und befand, dein Fang sei das Beste, was es je gefressen hat. Es verdaut noch die Gräten."
	L["good.core.toaststyle.ooze.name"] = "Glibber"
	L["good.core.toaststyle.page.description"] = "Eine frische Seite, aus dem Logbuch gerissen und an einen Lederrücken geheftet. Messingbeschlag, rote Tinte."
	L["good.core.toaststyle.page.name"] = "Abgerissene Seite"
	L["good.core.toaststyle.pirate.description"] = "Vom Deck eines Schiffs gehebelt, das nur je eine Flagge führte. Die Mannschaft ist längst fort; der Papagei erinnert sich an jeden Fisch und erzählt dir davon, laut."
	L["good.core.toaststyle.pirate.name"] = "Schwarze Flagge"
	L["good.core.toaststyle.ripple.description"] = "Blaues Leder und Silberbeschlag, und über die Seite ziehen feine Ringe, als hätte eben etwas gebissen."
	L["good.core.toaststyle.ripple.name"] = "Wellenringe"
	L["good.core.toaststyle.robot.description"] = "Gebaut, um zu angeln, während sein Erbauer schlief. Er hat nie geschlafen, nie geblinzelt und nie einen Fisch entkommen lassen. Das rote Auge heißt, er denkt nach."
	L["good.core.toaststyle.robot.name"] = "Mechanischer Angler"
	L["good.core.toaststyle.rune.description"] = "Gar kein Papier: eine Bronzeplatte, der Fang eingehämmert und die Runen ringsum geschnitten, damit alles ehrlich bleibt."
	L["good.core.toaststyle.rune.name"] = "Runenplatte"
	L["good.core.toaststyle.ship.description"] = "Eine Seite aus dem Logbuch des Schiffs, an einen Rücken aus Segeltuch gezurrt. Gezeitenspalten in Marineblau liniert, ein Anker am Rand."
	L["good.core.toaststyle.ship.name"] = "Schiffslogbuch"
	L["good.core.toaststyle.sonar.description"] = "Gebaut von einem Ingenieur, der die Fische sehen wollte, bevor sie ihn sahen. Er summt, er pingt, und bei einem Ping lag er noch nie falsch."
	L["good.core.toaststyle.sonar.name"] = "Sonarschirm"
	L["good.core.toaststyle.spider.description"] = "Über Nacht quer über das Fenster des Bootshauses gesponnen. Was sich darin fing, gehörte zuerst ihr; sie leiht dir nur den Namen."
	L["good.core.toaststyle.spider.name"] = "Netz der Witwe"
	L["good.core.toaststyle.storm.description"] = "Der Fang, den du gemacht hast, als alle Vernünftigen schon drinnen waren. Der Wimpel sagt Sturm; der Angler sagt: noch ein Wurf."
	L["good.core.toaststyle.storm.name"] = "Sturmfront"
	L["good.core.toaststyle.tidepool.description"] = "Eine Seite, die ins Wasser fiel und wieder herauskam. Sand im Falz, eine Muschel zurückgelassen."
	L["good.core.toaststyle.tidepool.name"] = "Gezeitentümpel"
	L["variety.12238.barred.description"] = "Breite dunkle Querbinden, die verblassen, wenn er ruht. Er ruht oft."
	L["variety.12238.barred.name"] = "Quergestreift"
	L["variety.12238.bigmouth.description"] = "Ein Maul, das eine Laterne schlucken könnte. Hat es vielleicht schon."
	L["variety.12238.bigmouth.name"] = "Weitmaul"
	L["variety.12238.brown.description"] = "Braun aus schlammigen Mündungen. Ergibt denselben Eintopf."
	L["variety.12238.brown.name"] = "Braun"
	L["variety.12238.coast-grey.description"] = "Grau, dunkler grau gesprenkelt, breit wie ein Schild. Bewegt sich nur, wenn er muss."
	L["variety.12238.coast-grey.name"] = "Küstengrau"
	L["variety.12238.moon-pale.description"] = "Blassgrau, als hätte der Mond ihn ausgebleicht. Ein besserer Eintopf, als der erste Eindruck verspricht."
	L["variety.12238.moon-pale.name"] = "Mondbleich"
	L["variety.12238.moonkissed.description"] = "Helle Sprenkel leuchten darauf wie Sterne auf dunklem Wasser. Bei Vollmond gefangen, wenn die Geschichten stimmen."
	L["variety.12238.moonkissed.name"] = "Mondgeküsst"
	L["variety.12238.mottled.description"] = "Dunkle Flecken wie Felsen unter flachem Wasser. Sitzt still und wartet."
	L["variety.12238.mottled.name"] = "Marmoriert"
	L["variety.12238.night-dark.description"] = "Fast schwarz, aus dem tiefsten Teil der Bucht. Niemand sieht ihn, bis er beißt."
	L["variety.12238.night-dark.name"] = "Nachtdunkel"
	L["variety.12238.rust-spotted.description"] = "Rostflecken auf Grau, wie ein Anker, der zu lange draußen lag."
	L["variety.12238.rust-spotted.name"] = "Rostfleck"
	L["variety.12238.silverscale.description"] = "Silbern, wo er grau sein sollte. Küstenangler sagen, er bringt Glück. Küstenangler brauchen Glück."
	L["variety.12238.silverscale.name"] = "Silberschuppe"
	L["variety.13422.banded.description"] = "Ringe aus dunklem Stein über die ganze Länge, wie eine gemeißelte Säule."
	L["variety.13422.banded.name"] = "Gebändert"
	L["variety.13422.bedrock-ancient.description"] = "Riesige Steinschuppen, rissig, mit bernsteinfarbenem Glühen in den Fugen. So alt wie die Klippe, aus der er kam, dem Anschein nach."
	L["variety.13422.bedrock-ancient.name"] = "Urgestein"
	L["variety.13422.gold-veined.description"] = "Gold zieht sich durchs Grau wie Erz durch Fels. Juweliere sollen schon geweint haben."
	L["variety.13422.gold-veined.name"] = "Goldader"
	L["variety.13422.greenstone.description"] = "Moosgrüne Schuppen. Sieht aus, als hätte er ein Jahrhundert im Flussbett gelegen."
	L["variety.13422.greenstone.name"] = "Grünstein"
	L["variety.13422.marble.description"] = "Weiß mit grauen Adern wie ein Tempelboden. Rüstungsschmiede streiten sich darum."
	L["variety.13422.marble.name"] = "Marmor"
	L["variety.13422.moray-spotted.description"] = "Überall dunkle Flecken wie die Haut einer Muräne. Freut sich genauso, dich zu sehen."
	L["variety.13422.moray-spotted.name"] = "Muränenfleck"
	L["variety.13422.obsidian.description"] = "Schwarze, glasige Schuppen, jede mit scharfer Kante. Am Schwanz anfassen, und vorsichtig."
	L["variety.13422.obsidian.name"] = "Obsidian"
	L["variety.13422.pebble-scaled.description"] = "Schuppen wie kleine graue Steine. Rüstungsschmiede zahlen gut. Der Aal sieht das anders."
	L["variety.13422.pebble-scaled.name"] = "Kieselschuppe"
	L["variety.13422.sandstone.description"] = "Warme, sandfarbene Schuppen von Wüstenküsten. Beißt trotzdem."
	L["variety.13422.sandstone.name"] = "Sandstein"
	L["variety.13422.slate.description"] = "Blaugrau wie Dachschiefer. Genauso schwer zu schneiden."
	L["variety.13422.slate.name"] = "Schiefer"
	L["variety.13754.barred.description"] = "Breite Querbinden über dem Glanz, wie ein Fisch im Schlachtgewand."
	L["variety.13754.barred.name"] = "Quergestreift"
	L["variety.13754.bronzeback.description"] = "Ein bronzener Rücken und ein heller Bauch. Schwer genug, um ein Boot zu verankern."
	L["variety.13754.bronzeback.name"] = "Bronzerücken"
	L["variety.13754.cobalt.description"] = "Tiefes Kobaltblau, das violett schimmert. Sieht aus wie ein Juwel. Wiegt wie ein Amboss."
	L["variety.13754.cobalt.name"] = "Kobalt"
	L["variety.13754.dappled.description"] = "Lichttupfen über dem Rücken wie Sonne durch flaches Wasser."
	L["variety.13754.dappled.name"] = "Lichtgetupft"
	L["variety.13754.green-glass.description"] = "Grün wie eine gegen das Licht gehaltene Flasche. Genauso schwer."
	L["variety.13754.green-glass.name"] = "Grünglas"
	L["variety.13754.humpbacked.description"] = "Ein Muskelbuckel hinter dem Kopf. Zieht wie ein Maultier."
	L["variety.13754.humpbacked.name"] = "Buckel"
	L["variety.13754.mirror.description"] = "So glänzend, dass ein Angler darin die Frisur prüfen könnte. Nach dem Kampf lassen es die meisten."
	L["variety.13754.mirror.name"] = "Spiegel"
	L["variety.13754.onyx.description"] = "Schwarzer Glanz wie Lack. Schluckt das Licht, und den Haken."
	L["variety.13754.onyx.name"] = "Onyx"
	L["variety.13754.polished.description"] = "Gedrungen, blau und poliert wie ein neuer Stiefel. Zieht wie etwas doppelt so Großes."
	L["variety.13754.polished.name"] = "Poliert"
	L["variety.13754.tidemight.description"] = "Linien aus Meereslicht laufen unter dem Glanz. Zieht, als hinge die Flut selbst am anderen Ende."
	L["variety.13754.tidemight.name"] = "Gezeitenkraft"
	L["variety.13755.blueflash.description"] = "Blitzt blau auf, wenn man ihn berührt. Er mag es nicht, berührt zu werden."
	L["variety.13755.blueflash.name"] = "Blaublitz"
	L["variety.13755.blushing.description"] = "Ganz rot angelaufen, wie Kalmare, wenn sie erschrecken. Meist vor dem Angler."
	L["variety.13755.blushing.name"] = "Errötet"
	L["variety.13755.brindled.description"] = "Dunkle Streifen über den Mantel, wie Frostrisse in einer Fensterscheibe."
	L["variety.13755.brindled.name"] = "Gestromt"
	L["variety.13755.crimson.description"] = "Ganz in tiefem Karmesin, der Farbe einer Warnung. Tintet doppelt so viel."
	L["variety.13755.crimson.name"] = "Karmesin"
	L["variety.13755.frost-pink.description"] = "Blassrosa, gesprenkelt mit dunklen Punkten, die beim Atmen kommen und gehen. Kommt mit dem Frost."
	L["variety.13755.frost-pink.name"] = "Frostrosa"
	L["variety.13755.frostlight.description"] = "Leuchtet im Dunkeln blassblau, wie Mondlicht auf Neuschnee. Nur in der tiefsten Kälte zu sehen."
	L["variety.13755.frostlight.name"] = "Frostlicht"
	L["variety.13755.glassfrost.description"] = "Klar wie Eis, an den Rändern bereift. Schmilzt in der Hand ein wenig, oder scheint es."
	L["variety.13755.glassfrost.name"] = "Glasfrost"
	L["variety.13755.long-armed.description"] = "Arme doppelt so lang wie üblich. Mehr zu entwirren, was unmöglich schien."
	L["variety.13755.long-armed.name"] = "Langarm"
	L["variety.13755.milky.description"] = "Weiß und fast durchsichtig. Leicht im Eis zu verlieren."
	L["variety.13755.milky.name"] = "Milchig"
	L["variety.13755.ring-spotted.description"] = "Dunkle Ringe über den Mantel, wie eine Reihe wachsamer Augen."
	L["variety.13755.ring-spotted.name"] = "Ringfleck"
	L["variety.13756.bronze.description"] = "Bronze mit schwachen Querbinden, aus felsigem Wasser. Springt mehr als die grünen."
	L["variety.13756.bronze.name"] = "Bronze"
	L["variety.13756.bucketmouth.description"] = "Ein Maul wie ein Eimer. Schluckt Köder im Ganzen und manchmal kleine Enten."
	L["variety.13756.bucketmouth.name"] = "Eimermaul"
	L["variety.13756.golden.description"] = "Gold mit einem bronzenen Streifen. Ein Sommernachmittag von einem Fisch."
	L["variety.13756.golden.name"] = "Golden"
	L["variety.13756.lateral-lined.description"] = "Grün mit einer dunklen Linie auf jeder Flanke. Lauert unter allem, was Schatten wirft."
	L["variety.13756.lateral-lined.name"] = "Seitenlinie"
	L["variety.13756.lily-pad.description"] = "Gefleckt wie ein Teich voller Seerosenblätter, und genau dort lauert er."
	L["variety.13756.lily-pad.name"] = "Seerosenblatt"
	L["variety.13756.midsummer.description"] = "Leuchtet warm golden wie der längste Abend des Jahres. Nur auf dem Höhepunkt des Sommers gefangen, und nur dann."
	L["variety.13756.midsummer.name"] = "Mittsommer"
	L["variety.13756.red-eyed.description"] = "Augen rot wie ein Sonnenuntergang im Sommer. Frisst am gierigsten in der Abendhitze."
	L["variety.13756.red-eyed.name"] = "Rotäugig"
	L["variety.13756.shadow.description"] = "Schwarzgrün und schwer zu sehen. Lebt im Schatten und mag es so."
	L["variety.13756.shadow.name"] = "Schatten"
	L["variety.13756.sun-bleached.description"] = "Blass vom flachen Sommerwasser, der Streifen zu einem Schmierer verblasst. Warm in der Hand."
	L["variety.13756.sun-bleached.name"] = "Sonnengebleicht"
	L["variety.13756.tiger.description"] = "Dunkle Querbinden, gebrochen wie Tigerstreifen. Kämpft auch wie einer, kurz."
	L["variety.13756.tiger.name"] = "Tiger"
	L["variety.13757.blackout.description"] = "Schwarz und still, bis man ihn berührt. Dann gar nicht mehr still."
	L["variety.13757.blackout.name"] = "Schwarzstille"
	L["variety.13757.bolt-striped.description"] = "Gelbe Zickzacklinien die Flanken hinab, wie ein Kinderbild von einem Blitz."
	L["variety.13757.bolt-striped.name"] = "Blitzstreifen"
	L["variety.13757.ember-bellied.description"] = "Ein orangefarbener Bauch wie bei Zitteraalen warmer Flüsse. Beißt mit einem Funken."
	L["variety.13757.ember-bellied.name"] = "Glutbauch"
	L["variety.13757.long.description"] = "Eine Flosse über die ganze Körperlänge. Sie flattert wie eine Fahne im Sturm."
	L["variety.13757.long.name"] = "Langflosse"
	L["variety.13757.ozone.description"] = "Riecht nach Regen nach einem Gewitter. Die Luft um ihn wird scharf."
	L["variety.13757.ozone.name"] = "Ozon"
	L["variety.13757.slate.description"] = "Grau wie Gewitterwolken. Summt einen tieferen Ton."
	L["variety.13757.slate.name"] = "Schiefer"
	L["variety.13757.spark-spotted.description"] = "Helle Flecken, die knistern, wenn er zappelt. Handschuhe helfen nicht."
	L["variety.13757.spark-spotted.name"] = "Funkenfleck"
	L["variety.13757.stormcaller.description"] = "Blaue Blitze gabeln sich über den Körper und ins Wasser. Wolken ziehen auf, solange er an der Schnur hängt, oder es scheint so."
	L["variety.13757.stormcaller.name"] = "Sturmrufer"
	L["variety.13757.thunder-dark.description"] = "Olivdunkel und summend. Kribbelt. Nicht ablecken."
	L["variety.13757.thunder-dark.name"] = "Donnerdunkel"
	L["variety.13757.white-bolt.description"] = "Weiß wie ein Blitzstrahl und kurz blendend, wenn er sich windet."
	L["variety.13757.white-bolt.name"] = "Grellblitz"
	L["variety.13758.cinder.description"] = "Aschgrau mit rot glühenden Kiemen, wie eine Kohle aus einem erloschenen Feuer."
	L["variety.13758.cinder.name"] = "Aschenglut"
	L["variety.13758.ember-gilled.description"] = "Quergestreift wie ein Barsch, mit Kiemen rot wie Glut. Das übliche Aussehen, und das übliche Temperament."
	L["variety.13758.ember-gilled.name"] = "Glutkieme"
	L["variety.13758.fel-scarred.description"] = "Grünes Feuer läuft unter den Schuppen, wo das Rot sein sollte. Er kam aus Wasser, das sich an eine Verderbnis erinnert."
	L["variety.13758.fel-scarred.name"] = "Teufelsnarbe"
	L["variety.13758.fire-gilled.description"] = "Die Kiemen glühen tatsächlich. Niemand ist sicher, ob das Wasser kalt genug war."
	L["variety.13758.fire-gilled.name"] = "Feuerkieme"
	L["variety.13758.ghost.description"] = "Bleich, mit rosa Kiemen und schwachen Querbinden. Fühlt sich selbst im Sommer kalt an."
	L["variety.13758.ghost.name"] = "Geist"
	L["variety.13758.golden.description"] = "Gold mit scharlachroten Kiemen. Sieht aus wie etwas aus dem Brunnen eines Lords."
	L["variety.13758.golden.name"] = "Golden"
	L["variety.13758.olive.description"] = "Dunkleres Oliv, aus zugewachsenen Flüssen. Die Kiemen leuchten dagegen umso heller."
	L["variety.13758.olive.name"] = "Oliv"
	L["variety.13758.redfin.description"] = "Flossen so rot wie die Kiemen. Der ganze Fisch sieht wütend aus, weil er es ist."
	L["variety.13758.redfin.name"] = "Rotflosse"
	L["variety.13758.spotted.description"] = "Flecken statt Querbinden. Gleiches Temperament."
	L["variety.13758.spotted.name"] = "Gefleckt"
	L["variety.13758.yellow.description"] = "Goldgelb mit dunklen Querbinden. Hell wie eine Lampe in grünem Wasser."
	L["variety.13758.yellow.name"] = "Gelb"
	L["variety.13759.crescent-marked.description"] = "Eine helle Sichel auf jeder Flanke, als hätte der Mond einen Fingerabdruck hinterlassen."
	L["variety.13759.crescent-marked.name"] = "Mondsichel"
	L["variety.13759.dawn-caught.description"] = "Rosa und gold, gefangen, als die Nacht endete. Ein Nachtfisch, der zu lange aufgeblieben ist."
	L["variety.13759.dawn-caught.name"] = "Morgengrauen"
	L["variety.13759.dusk.description"] = "Violetter Rücken, rosa Bauch, wie der Himmel kurz nach Sonnenuntergang."
	L["variety.13759.dusk.name"] = "Abenddämmerung"
	L["variety.13759.eclipse.description"] = "Schwarz, an den Flossen golden gesäumt, wie die verdunkelte Sonne."
	L["variety.13759.eclipse.name"] = "Finsternis"
	L["variety.13759.indigo.description"] = "Tiefes Indigo. Verschwindet im Wasser, sobald der Mond sich verzieht."
	L["variety.13759.indigo.name"] = "Indigo"
	L["variety.13759.moonfin.description"] = "Silberweiße Flossen, die das Mondlicht fangen. Angler lernen, die Dunkelheit zu mögen."
	L["variety.13759.moonfin.name"] = "Mondflosse"
	L["variety.13759.owl-eyed.description"] = "Riesige goldene Augen, gemacht für die Dunkelheit. Starrt direkt zurück."
	L["variety.13759.owl-eyed.name"] = "Eulenauge"
	L["variety.13759.star-speckled.description"] = "Helle Sprenkel den Rücken entlang, wie ein Himmel mit ein paar Sternen."
	L["variety.13759.star-speckled.name"] = "Sternsprenkel"
	L["variety.13759.starfeeder.description"] = "Dunkelviolett mit Flossen wie die Nacht. Frisst im Sternenlicht."
	L["variety.13759.starfeeder.name"] = "Sternfresser"
	L["variety.13759.starsong.description"] = "Die Sprenkel leuchten wie der Nachthimmel und wandern beim Drehen, wie kreisende Sterne. Auf dem Steg wird es still."
	L["variety.13759.starsong.name"] = "Sternenlied"
	L["variety.13760.coin-scaled.description"] = "Silbern mit goldgefleckten Schuppen, die das Licht fangen wie Münzen in einem Bach."
	L["variety.13760.coin-scaled.name"] = "Münzschuppe"
	L["variety.13760.copper.description"] = "Poliertes Kupfer von Kopf bis Schwanz. Schmeckt nach Lachs, sieht aus wie ein Kessel."
	L["variety.13760.copper.name"] = "Kupfer"
	L["variety.13760.hooknose.description"] = "Ein grimmiger Hakenkiefer vom Zug flussaufwärts. Sieht bereit aus, mit einem Bären zu kämpfen."
	L["variety.13760.hooknose.name"] = "Hakennase"
	L["variety.13760.morning.description"] = "Am Bauch pfirsichfarben angehaucht, wie das erste Licht auf einem Fluss."
	L["variety.13760.morning.name"] = "Morgen"
	L["variety.13760.noonday.description"] = "Gold den ganzen Rücken entlang, wie ein Fluss zur Mittagszeit."
	L["variety.13760.noonday.name"] = "Mittag"
	L["variety.13760.red-run.description"] = "Rot geworden für den Laichzug, mit grünem Kopf. In einem guten Jahr färbt sich der Fluss rot von ihnen."
	L["variety.13760.red-run.name"] = "Rotzug"
	L["variety.13760.river-dark.description"] = "Dunkler, aus schattigen Flüssen. Die Goldflecken stechen hervor."
	L["variety.13760.river-dark.name"] = "Flussdunkel"
	L["variety.13760.silverbright.description"] = "Hell silbern, frisch aus dem Meer. Kaum ein Goldfleck."
	L["variety.13760.silverbright.name"] = "Silberhell"
	L["variety.13760.sunfire.description"] = "Jede Schuppe golden erleuchtet wie eine winzige Sonne. Warm wie ein Herdstein. Kaum direkt anzusehen."
	L["variety.13760.sunfire.name"] = "Sonnenfeuer"
	L["variety.13760.twilight.description"] = "Violett und orange, wie das letzte Licht auf dem Fluss. Bei voller Dunkelheit verschwunden."
	L["variety.13760.twilight.name"] = "Zwielicht"
	L["variety.13888.abyssal.description"] = "Violettes Licht glüht aus den Gelenken des Panzers. Aus sehr tiefem Wasser heraufgeklettert, und sichtlich verärgert darüber."
	L["variety.13888.abyssal.name"] = "Abgrund"
	L["variety.13888.barnacled.description"] = "Überall Seepocken auf dem Panzer. Hat sich lange nicht gehäutet und bereut nichts."
	L["variety.13888.barnacled.name"] = "Seepocken"
	L["variety.13888.bigclaw.description"] = "Eine Schere doppelt so groß wie die andere. Weiß genau, welche er benutzt."
	L["variety.13888.bigclaw.name"] = "Riesenschere"
	L["variety.13888.blue-black.description"] = "Blauschwarzer Panzer, leicht gesprenkelt, Scheren voran. Die Sorte, die sich unter jedem Stein der Bucht versteckt."
	L["variety.13888.blue-black.name"] = "Blauschwarz"
	L["variety.13888.calico.description"] = "Orange und schwarz gefleckt wie eine Schildpattkatze. Kaum jemand glaubt es."
	L["variety.13888.calico.name"] = "Dreifarbig"
	L["variety.13888.ghost.description"] = "Weiß wie Knochen. Selbst die Scheren sind bleich. Das Temperament nicht."
	L["variety.13888.ghost.name"] = "Geist"
	L["variety.13888.mud-brown.description"] = "Braun von schlammigen Bänken. Kneift genauso fest."
	L["variety.13888.mud-brown.name"] = "Schlammbraun"
	L["variety.13888.red-banded.description"] = "Rote Bänder über den Schwanz. Sieht schon halb gekocht aus. Ist er nicht."
	L["variety.13888.red-banded.name"] = "Rotband"
	L["variety.13888.sapphire.description"] = "Ganz leuchtend blau. Einer unter sehr vielen. Kneift wie die anderen."
	L["variety.13888.sapphire.name"] = "Saphir"
	L["variety.13888.sea-green.description"] = "Grünschwarz, wie ein Hummer kälterer Meere."
	L["variety.13888.sea-green.name"] = "Meergrün"
	L["variety.13889.ashen.description"] = "Grau wie Asche, aus Gewässern nahe den verseuchten Landen. Trotzdem gut zu essen, heißt es."
	L["variety.13889.ashen.name"] = "Aschgrau"
	L["variety.13889.crystal.description"] = "Stellenweise klar wie Eis. Die Pfanne wirkt irgendwie falsch."
	L["variety.13889.crystal.name"] = "Kristall"
	L["variety.13889.frost-white.description"] = "Blasses Silber, leicht gesprenkelt, kalt in der Hand, egal wie lange er in der Sonne liegt."
	L["variety.13889.frost-white.name"] = "Frostbleich"
	L["variety.13889.hooknose.description"] = "Ein Hakenkiefer und ein kalter Blick. Frost auf Barteln, die er gar nicht hat."
	L["variety.13889.hooknose.name"] = "Hakennase"
	L["variety.13889.hot-spring.description"] = "Wärmer getönt, aus Gewässern, wo die Quellen aufsteigen. Dampft, wenn er an Land kommt."
	L["variety.13889.hot-spring.name"] = "Thermalquelle"
	L["variety.13889.pearl.description"] = "Perlmuttglanz ganz ohne Flecken. Sieht geschnitzt aus."
	L["variety.13889.pearl.name"] = "Perle"
	L["variety.13889.silverblue.description"] = "Ein blauer Schimmer auf dem Rücken, von Gletscherwasser."
	L["variety.13889.silverblue.name"] = "Silberblau"
	L["variety.13889.snowflake.description"] = "Leuchtend weiße Tupfen auf Silber, wie Schnee auf einem gefrorenen See."
	L["variety.13889.snowflake.name"] = "Schneeflocke"
	L["variety.13889.spawn-blush.description"] = "Ein rosa Hauch an den Flanken zur Laichzeit. Selten in so kaltem Wasser."
	L["variety.13889.spawn-blush.name"] = "Laichröte"
	L["variety.13889.wintersheen.description"] = "Frostmuster bedecken jede Schuppe und glühen schwach blau. Er taut nie auf, nicht einmal in der Pfanne."
	L["variety.13889.wintersheen.name"] = "Winterglanz"
	L["variety.13890.ancient-bulwark.description"] = "Platten dick wie Schilde, mit alten, golden glühenden Linien. Als hätte ihn jemand vor langer Zeit geschmiedet und schwimmen lassen."
	L["variety.13890.ancient-bulwark.name"] = "Uraltes Bollwerk"
	L["variety.13890.battle-scarred.description"] = "Verbeulte Platten und alte Furchen. Was auch immer ihn fressen wollte, hat aufgegeben."
	L["variety.13890.battle-scarred.name"] = "Kampfnarbe"
	L["variety.13890.bony-backed.description"] = "Knochenplatten den Rücken hinab wie beim Stör. Trägt die Rüstung außen, das Temperament innen."
	L["variety.13890.bony-backed.name"] = "Knochenrücken"
	L["variety.13890.bronze-plated.description"] = "Platten in der Farbe alter Bronze. Sieht paradetauglich aus."
	L["variety.13890.bronze-plated.name"] = "Bronzeplatte"
	L["variety.13890.gilded.description"] = "Goldgesäumte Platten wie die Paraderüstung eines Ritters. Kämpft auch wie ein Ritter."
	L["variety.13890.gilded.name"] = "Vergoldet"
	L["variety.13890.iron-plated.description"] = "Graue Platten wie eine Eisenrüstung. Ein schwereres Messer mitbringen."
	L["variety.13890.iron-plated.name"] = "Eisenplatte"
	L["variety.13890.moss-backed.description"] = "Grünes Moos auf den Platten. Hat sich lange nicht bewegt, dann plötzlich doch."
	L["variety.13890.moss-backed.name"] = "Moosrücken"
	L["variety.13890.ore-plated.description"] = "Platten mit grüngrauem Glanz, wie das härteste Erz der Berge. Das Messer gibt zuerst auf."
	L["variety.13890.ore-plated.name"] = "Erzplatte"
	L["variety.13890.ring-plated.description"] = "Platten in sauberen Ringen, wie ein Bänderpanzer."
	L["variety.13890.ring-plated.name"] = "Ringplatte"
	L["variety.13890.spiked.description"] = "Jede Platte mit einem Stachel. Vernünftige Angler nehmen den Kescher."
	L["variety.13890.spiked.name"] = "Stachelig"
	L["variety.13893.abyss-dark.description"] = "Schwarzblau, aus dem tiefsten Graben der Bucht. Zerrt, als wollte der Graben ihn zurück."
	L["variety.13893.abyss-dark.name"] = "Abgrunddunkel"
	L["variety.13893.barred.description"] = "Breite dunkle Querbinden an den Seiten wie Spanten an einem Schiffsrumpf."
	L["variety.13893.barred.name"] = "Quergestreift"
	L["variety.13893.big-blue.description"] = "Riesig, blau und breit. Beide Hände, und vermutlich ein Freund."
	L["variety.13893.big-blue.name"] = "Blauriese"
	L["variety.13893.golden.description"] = "Ein goldener Riese. Ohne den Fisch glaubt niemand die Geschichte."
	L["variety.13893.golden.name"] = "Golden"
	L["variety.13893.hump-shouldered.description"] = "Ein großer Buckel hinter dem Kopf. Gebaut wie ein Anlegepfahl."
	L["variety.13893.hump-shouldered.name"] = "Buckelschulter"
	L["variety.13893.leviathans-get.description"] = "Leuchtende Linien wie alte Runen an den Flanken. Die ältesten Geschichten der Bucht handeln von etwas Größerem. Ein Anfang."
	L["variety.13893.leviathans-get.name"] = "Leviathanbrut"
	L["variety.13893.old-scarback.description"] = "Narben von Zähnen, größer, als irgendein Angler sie je treffen möchte."
	L["variety.13893.old-scarback.name"] = "Alter Narbenrücken"
	L["variety.13893.sea-green.description"] = "Grün wie tiefes Wasser. Es braucht drei, um ihn ins Boot zu ziehen."
	L["variety.13893.sea-green.name"] = "Meergrün"
	L["variety.13893.spotted.description"] = "Helle Flecken auf dunklem Rücken wie Schaum auf einer Welle."
	L["variety.13893.spotted.name"] = "Gefleckt"
	L["variety.13893.storm-grey.description"] = "Grau wie die Bucht im Sturm. Fühlt sich an, als wöge er genauso viel."
	L["variety.13893.storm-grey.name"] = "Sturmgrau"
	L["variety.1467.barred.description"] = "Schwache Streifen die Flanken hinab, wie die Jungen sie tragen. Manche wachsen nie heraus."
	L["variety.1467.barred.name"] = "Quergestreift"
	L["variety.1467.blue-cheeked.description"] = "Zwei blaue Linien auf jeder Wange, wie Kriegsbemalung für einen sehr kleinen Krieg."
	L["variety.1467.blue-cheeked.name"] = "Blauwange"
	L["variety.1467.copper-breasted.description"] = "Eine Brust wie ein polierter Kessel. Die Köche zögern, kurz."
	L["variety.1467.copper-breasted.name"] = "Kupferbrust"
	L["variety.1467.ember-spotted.description"] = "In den warmen Monaten werden die Flecken rot, als hätte er zu nah am Feuer gesessen."
	L["variety.1467.ember-spotted.name"] = "Glutfleck"
	L["variety.1467.golden.description"] = "Alles Grün verschwunden, nur Gold übrig. Reiher sehen ihn quer über den See."
	L["variety.1467.golden.name"] = "Golden"
	L["variety.1467.midnight.description"] = "Schwarz wie Seeschlamm, Flecken und alles. Leicht zu übersehen, und genau darum geht es."
	L["variety.1467.midnight.name"] = "Mitternacht"
	L["variety.1467.pale-shallows.description"] = "Ausgebleicht von warmem Flachwasser und langen Nachmittagen. Die Flecken geben sich kaum Mühe."
	L["variety.1467.pale-shallows.name"] = "Blasses Flachwasser"
	L["variety.1467.peppered.description"] = "Flecken, zu Pfeffer gemahlen. Derselbe Fisch, feiner gewürzt."
	L["variety.1467.peppered.name"] = "Gepfeffert"
	L["variety.1467.sunburst.description"] = "Orange Strahlen laufen vom Auge aus wie der Morgen über stillem Wasser. Er bleibt warm in der Hand."
	L["variety.1467.sunburst.name"] = "Sonnenstrahl"
	L["variety.1467.sunset-breasted.description"] = "Olivgrüne Flanken, dunkle Flecken, eine Brust wie Abendrot über dem See. Der, den jeder kennt."
	L["variety.1467.sunset-breasted.name"] = "Abendrotbrust"
	L["variety.16967.feeding-barred.description"] = "Helle Querbinden blitzen an den Flanken, wie Thunfische sie bei der Jagd zeigen. Mitten beim Fressen gefangen."
	L["variety.16967.feeding-barred.name"] = "Jagdstreifen"
	L["variety.16967.ghostfin.description"] = "Ganz bleich, die Flossen fast durchsichtig. Schwimmt wie ein Spiegelbild."
	L["variety.16967.ghostfin.name"] = "Geisterflosse"
	L["variety.16967.gold-belted.description"] = "Ein goldener Streifen vom Auge bis zum Schwanz. Ein Gefallen in Fischform, im feinsten Gewand."
	L["variety.16967.gold-belted.name"] = "Goldgürtel"
	L["variety.16967.imperial.description"] = "Tiefes Königsblau mit leuchtend goldenen Flossen. Zu prächtig, um für irgendwen ein Gefallen zu sein."
	L["variety.16967.imperial.name"] = "Kaiserblau"
	L["variety.16967.leaf-lit.description"] = "Blassgrünes Licht wandert unter den Schuppen wie Sonne durch Laub. Die alte Magie des Waldes steckt in diesen Gewässern."
	L["variety.16967.leaf-lit.name"] = "Blattlicht"
	L["variety.16967.mossback.description"] = "Oben grünschwarz, als wüchse der Wald darauf. Schwimmt langsam, dann sehr schnell."
	L["variety.16967.mossback.name"] = "Moosrücken"
	L["variety.16967.sickle-fin.description"] = "Flossen, lang und gebogen wie Sicheln. Gebaut für lange Reisen flussabwärts."
	L["variety.16967.sickle-fin.name"] = "Sichelflosse"
	L["variety.16967.silverflank.description"] = "Helleres Silber die ganze Seite entlang. Die gelben Flossen wirken aufgemalt."
	L["variety.16967.silverflank.name"] = "Silberflanke"
	L["variety.16967.verdant.description"] = "Ein grüner Schimmer auf dem Rücken, vom Flusswasser unter den großen Bäumen."
	L["variety.16967.verdant.name"] = "Waldgrün"
	L["variety.16967.yellowfin.description"] = "Dunkelblauer Rücken, silberner Bauch, lange gelbe Flossen. Der Fisch, für den der Fluss berühmt ist."
	L["variety.16967.yellowfin.name"] = "Gelbflosse"
	L["variety.16968.blackback.description"] = "Oben schwarz, unten stahlgrau. Schlägt aus dem Dunkeln zu."
	L["variety.16968.blackback.name"] = "Schwarzrücken"
	L["variety.16968.bonecutter.description"] = "Zähne wie Knochensägen und ein Rücken voller alter Spuren. Geschichten von der trockenen Küste sagen, er habe drei Jäger überlebt."
	L["variety.16968.bonecutter.name"] = "Knochensäger"
	L["variety.16968.bronze.description"] = "Bronzene Querbinden, aus warmem Wasser. Doppeltes Temperament."
	L["variety.16968.bronze.name"] = "Bronze"
	L["variety.16968.chevron.description"] = "Dunkle Winkel den Rücken hinab wie Pfeile, die auf Ärger zeigen."
	L["variety.16968.chevron.name"] = "Pfeilmuster"
	L["variety.16968.ghost.description"] = "Weiß und fast durchsichtig, die Querbinden nur ein Schatten ihrer selbst. Die Zähne sind völlig echt."
	L["variety.16968.ghost.name"] = "Geist"
	L["variety.16968.greyback.description"] = "Oben schlicht grau, unten weiß. Nur Zähne und Absicht."
	L["variety.16968.greyback.name"] = "Graurücken"
	L["variety.16968.needlejaw.description"] = "Zähne wie eine Reihe Nadeln. Hinterher die Finger zählen."
	L["variety.16968.needlejaw.name"] = "Nadelkiefer"
	L["variety.16968.sandstrand.description"] = "Sandfarben, aus den Untiefen einer trockenen Küste. Unsichtbar, bis er zuschlägt."
	L["variety.16968.sandstrand.name"] = "Sandstrand"
	L["variety.16968.silver-barred.description"] = "Lang, silbern und quergestreift, mit einem Maul voller Zähne. Für eine einzige Sache gebaut."
	L["variety.16968.silver-barred.name"] = "Silberstreif"
	L["variety.16968.spotted.description"] = "Schwarze Flecken nahe dem Schwanz, wie sie die Großen bekommen. Wartet noch immer auf Streit."
	L["variety.16968.spotted.name"] = "Gefleckt"
	L["variety.16969.barred.description"] = "Hellblaue Querbinden an den Flanken, mitten im Kampf aufleuchtend. Am besten in der Luft zu sehen, wo er den Kampf verbringt."
	L["variety.16969.barred.name"] = "Quergestreift"
	L["variety.16969.jungle-green.description"] = "Grün wie der Dschungel hinter der Küste. Gibt trotzdem genauso an."
	L["variety.16969.jungle-green.name"] = "Dschungelgrün"
	L["variety.16969.royal.description"] = "Tiefes Königsblau, das Segel golden getupft. Angler halten ihn abwechselnd."
	L["variety.16969.royal.name"] = "Königsblau"
	L["variety.16969.silver.description"] = "Mehr silbern als blau. Das Segel bleibt so leuchtend wie immer."
	L["variety.16969.silver.name"] = "Silbern"
	L["variety.16969.skyleaper.description"] = "Linien aus blauem Licht laufen beim Sprung das Segel hinauf. Scheint länger in der Luft zu hängen, als ein Fisch sollte."
	L["variety.16969.skyleaper.name"] = "Himmelsspringer"
	L["variety.16969.spotted-sail.description"] = "Blauer Rücken, silberner Bauch, ein hohes, getupftes Segel. Stellt es auf, sobald jemand hinsieht."
	L["variety.16969.spotted-sail.name"] = "Tupfensegel"
	L["variety.16969.sunset-sail.description"] = "Ein orangefarbenes Segel, wie die Küste am Abend. Springt mehr als die blauen."
	L["variety.16969.sunset-sail.name"] = "Abendsegel"
	L["variety.16969.tall-sailed.description"] = "Ein Segel, höher als der Fisch tief ist. Der Wind erfasst es an der Schnur."
	L["variety.16969.tall-sailed.name"] = "Hochsegel"
	L["variety.16969.violet-sail.description"] = "Das Segel glüht violett, wenn er aufgeregt ist. Er ist immer aufgeregt."
	L["variety.16969.violet-sail.name"] = "Veilchensegel"
	L["variety.16969.white-sail.description"] = "Bleich wie Segeltuch. Seeleute schwören, er verheißt gutes Wetter."
	L["variety.16969.white-sail.name"] = "Segeltuch"
	L["variety.16970.barred.description"] = "Dunkle Querbinden blitzen an den Seiten auf, wenn er am Haken hängt. Er ist außer sich."
	L["variety.16970.barred.name"] = "Quergestreift"
	L["variety.16970.bluefin.description"] = "Blau an Rücken und Flossen. Kühler im Kopf. Nicht viel."
	L["variety.16970.bluefin.name"] = "Blauflosse"
	L["variety.16970.bull-headed.description"] = "Eine stumpfe, hohe Stirn wie ein Mahi-Bulle. Greift das Boot an."
	L["variety.16970.bull-headed.name"] = "Stierkopf"
	L["variety.16970.dorado.description"] = "Grün und gold mit blauen Flecken, wie ein Papagei, der mit dem Schwimmen angefangen hat."
	L["variety.16970.dorado.name"] = "Dorado"
	L["variety.16970.emerald.description"] = "Rein grün, ganz ohne Gold. Wie ein Edelstein, der ins Moor gefallen ist."
	L["variety.16970.emerald.name"] = "Smaragd"
	L["variety.16970.fog-pale.description"] = "Bleich, als wäre der Sumpfnebel in die Farbe gezogen. Kämpft wie eine Nebelbank, dann wie ein Maultier."
	L["variety.16970.fog-pale.name"] = "Nebelbleich"
	L["variety.16970.gold-flanked.description"] = "Mehr Gold als Grün. Wird kurz nach dem Landen grau, also schnell hinsehen."
	L["variety.16970.gold-flanked.name"] = "Goldflanke"
	L["variety.16970.marsh-lantern.description"] = "Die Flecken glühen grüngolden im Nebel wie Laternen im Sumpf. Die Einheimischen sagen, er führt Angler in die Irre."
	L["variety.16970.marsh-lantern.name"] = "Sumpflaterne"
	L["variety.16970.reed-green.description"] = "Mattgrün, aus dem nebligen Schilf. Kaum zu sehen, bis er springt."
	L["variety.16970.reed-green.name"] = "Schilfgrün"
	L["variety.16970.sunfire.description"] = "Orange und gold, wie ein Feuer am Ufer. Der Sumpf verstummt, um hinzusehen."
	L["variety.16970.sunfire.name"] = "Sonnenfeuer"
	L["variety.19807.big-spotted.description"] = "Flecken wie hingeworfene Münzen. Irgendwer behauptet immer, es sei ein anderer Fisch."
	L["variety.19807.big-spotted.name"] = "Münzfleck"
	L["variety.19807.black.description"] = "Schwarz mit weißen Sprenkeln, wie ein Nachthimmel in Eile."
	L["variety.19807.black.name"] = "Schwarz"
	L["variety.19807.champions.description"] = "Jeder Sprenkel glänzt wie eine Goldmünze. Ein Fisch, von dem man sich noch jahrelang erzählt."
	L["variety.19807.champions.name"] = "Siegerfang"
	L["variety.19807.contest-speckle.description"] = "Silbergrau und gesprenkelt. Jeder Teilnehmer auf dem Steg kennt ihn vom Sehen."
	L["variety.19807.contest-speckle.name"] = "Wettbewerbssprenkel"
	L["variety.19807.gilded.description"] = "Gold mit braunen Sommersprossen. Auf dem Steg bildet sich eine Menge."
	L["variety.19807.gilded.name"] = "Vergoldet"
	L["variety.19807.lucky-speckle.description"] = "Ein Sprenkel in Hufeisenform. Fürs Glück behalten, dann zu Mittag gegessen."
	L["variety.19807.lucky-speckle.name"] = "Glückssprenkel"
	L["variety.19807.olive.description"] = "Grüner Rücken, aus verkrauteten Untiefen. Die Teilnehmer greifen trotzdem zu."
	L["variety.19807.olive.name"] = "Oliv"
	L["variety.19807.pale.description"] = "Weiß mit schwachen cremefarbenen Sprenkeln. Zieht bei jedem Wettbewerb Blicke auf sich."
	L["variety.19807.pale.name"] = "Bleich"
	L["variety.19807.red-speckled.description"] = "Rote Sommersprossen. Sieht schon gewürzt aus."
	L["variety.19807.red-speckled.name"] = "Rotsprenkel"
	L["variety.19807.silver-speckle.description"] = "Helleres Silber, aus offenem Wasser. Dieselben Sprenkel."
	L["variety.19807.silver-speckle.name"] = "Silbersprenkel"
	L["variety.19975.bloodmud.description"] = "Dunkelrot, aus Schlamm, wo einst Opfer dargebracht wurden. Besser nicht nachfragen."
	L["variety.19975.bloodmud.name"] = "Blutschlamm"
	L["variety.19975.idol-touched.description"] = "Schwache rotviolette Adern glühen auf dem Rücken wie alte Götzenfarbe. Selbst die Bestien dieser Gewässer halten Abstand."
	L["variety.19975.idol-touched.name"] = "Götzenberührt"
	L["variety.19975.jungle-mud.description"] = "Grünbraun, aus tiefem Dschungelschlamm. Riecht auch danach."
	L["variety.19975.jungle-mud.name"] = "Dschungelschlamm"
	L["variety.19975.long-whiskered.description"] = "Lange Barteln, die durch den Schlamm schleifen. Findet jeden Köder, riecht jeden."
	L["variety.19975.long-whiskered.name"] = "Langbartel"
	L["variety.19975.masked.description"] = "Ein dunkles Band über den Augen wie eine geschnitzte Maske. Sieht aus, als wüsste er Dinge."
	L["variety.19975.masked.name"] = "Maske"
	L["variety.19975.ochre.description"] = "Ockergelb wie der Ton, mit dem die Trolle malen. Riecht nicht besser."
	L["variety.19975.ochre.name"] = "Ocker"
	L["variety.19975.pale.description"] = "Knochenbleich, aus Wasser unter uraltem Stein. Der Geruch überdauert die Farbe."
	L["variety.19975.pale.name"] = "Bleich"
	L["variety.19975.skunk-striped.description"] = "Ein heller Streifen von Kopf bis Schwanz. Eine Warnung, und eine faire."
	L["variety.19975.skunk-striped.name"] = "Stinktierstreifen"
	L["variety.19975.slimeback.description"] = "Braun, schleimig und gedrungen. Die Nase findet ihn vor den Augen."
	L["variety.19975.slimeback.name"] = "Schleimrücken"
	L["variety.19975.spotted.description"] = "Dunkle Flecken auf Braun, wie Schlamm auf Schlamm gespritzt."
	L["variety.19975.spotted.name"] = "Gefleckt"
	L["variety.21071.banded.description"] = "Schwache Bänder wie Reihen in einem Kräutergarten."
	L["variety.21071.banded.name"] = "Gebändert"
	L["variety.21071.dark-sage.description"] = "Tiefgrün, aus schattigen Bächen. Riecht stärker."
	L["variety.21071.dark-sage.name"] = "Dunkelsalbei"
	L["variety.21071.frost-sage.description"] = "Blass, jede Schuppe mit bereiftem Rand. Schmeckt irgendwie reiner."
	L["variety.21071.frost-sage.name"] = "Frostsalbei"
	L["variety.21071.gold-sage.description"] = "Gelbgrün wie trockenes Sommergras. Riecht nach einem langen heißen Tag."
	L["variety.21071.gold-sage.name"] = "Goldsalbei"
	L["variety.21071.hillside.description"] = "Salbeigrün und gesprenkelt, wie die Hügel über dem Bach, aus dem er kam."
	L["variety.21071.hillside.name"] = "Hügelhang"
	L["variety.21071.lavender-finned.description"] = "Flossen in Lavendelfarbe. Riecht auch ein wenig danach."
	L["variety.21071.lavender-finned.name"] = "Lavendelflosse"
	L["variety.21071.mindbright.description"] = "Blasses Licht flackert in den Linien der Schuppen. Angler, die ihn essen, sagen, sie dächten klarer. Das sagen sie oft."
	L["variety.21071.mindbright.name"] = "Geistesklar"
	L["variety.21071.silver-sage.description"] = "Silbrig, wie Salbeiblätter, die der Wind umdreht."
	L["variety.21071.silver-sage.name"] = "Silbersalbei"
	L["variety.21071.sweetgrass.description"] = "Leuchtend grün und süß duftend. Der einzige Fisch, den je jemand zur Wäsche in die Schublade legen wollte."
	L["variety.21071.sweetgrass.name"] = "Duftgras"
	L["variety.21071.thyme-spotted.description"] = "Winzige lila Tupfen wie Thymianblüten. Die Köche sind einverstanden."
	L["variety.21071.thyme-spotted.name"] = "Thymiantupfen"
	L["variety.21153.ashen.description"] = "Grau wie Rauch, und er riecht schwach nach Weihrauch. Niemand verbrennt mehr Salbei am Wasser."
	L["variety.21153.ashen.name"] = "Aschgrau"
	L["variety.21153.banded.description"] = "Breite Bänder wie die Ringe eines Baumes. Die alten haben mehr."
	L["variety.21153.banded.name"] = "Gebändert"
	L["variety.21153.bearded.description"] = "Lange, nachschleifende Flossen wie der Bart eines alten Weisen. Sieht weiser aus, als er ist."
	L["variety.21153.bearded.name"] = "Rauschebart"
	L["variety.21153.bronze.description"] = "Bronzefarben, aus gerbstoffdunklen Flüssen. Schmeckt leicht nach Tee."
	L["variety.21153.bronze.name"] = "Bronze"
	L["variety.21153.elder-sage.description"] = "Alt, riesig, die Schuppen von blassgoldenen Linien erleuchtet wie Adern in einem Blatt. Manche Orte bewahren ihre ältesten Dinge."
	L["variety.21153.elder-sage.name"] = "Uralter Salbei"
	L["variety.21153.full-grown.description"] = "Der Salbei ist aufgegangen: größer, dunkler, noch immer duftend."
	L["variety.21153.full-grown.name"] = "Ausgewachsen"
	L["variety.21153.golden.description"] = "Golden und duftend. Riecht nach Honig auf warmem Stein."
	L["variety.21153.golden.name"] = "Golden"
	L["variety.21153.moss-green.description"] = "Gefleckt wie Moos auf altem Stein. Riecht nach feuchtem Wald."
	L["variety.21153.moss-green.name"] = "Moosgrün"
	L["variety.21153.silver.description"] = "Ein silberner Riese seiner Art. Wurde groß und hell."
	L["variety.21153.silver.name"] = "Silbern"
	L["variety.21153.violet-finned.description"] = "Lila Flossen, wie blühender Salbei. Im Frühling duftet er stärker."
	L["variety.21153.violet-finned.name"] = "Veilchenflosse"
	L["variety.251524.dreamfin.description"] = "Leuchtet zart rosa und blau und hinterlässt einen schwachen Schimmer im Wasser. Kleinen Kindern erzählt man, er erfülle Wünsche. Niemand prüft es nach."
	L["variety.251524.dreamfin.name"] = "Traumflosse"
	L["variety.251524.frill-finned.description"] = "Flossen wie Spitzenrüschen. Hoffnungslos im Schwimmen, aber trotzdem entzückt."
	L["variety.251524.frill-finned.name"] = "Rüschenflosse"
	L["variety.251524.lemon.description"] = "Zitronengelb mit blauen Punkten. Scheint sich sehr über etwas zu freuen."
	L["variety.251524.lemon.name"] = "Zitrone"
	L["variety.251524.lilac.description"] = "Fliederfarben mit cremefarbenen Streifen. Schwimmt in Schleifen, ohne erkennbaren Grund."
	L["variety.251524.lilac.name"] = "Flieder"
	L["variety.251524.mint.description"] = "Minzgrün mit rosa Punkten. Sieht aus wie eine Süßigkeit vom Jahrmarkt."
	L["variety.251524.mint.name"] = "Minze"
	L["variety.251524.murk-touched.description"] = "Dunkelviolett, die Punkte gedämpft. Der Einzige seiner Art, der aussieht, als hätte er einen schlechten Tag gehabt."
	L["variety.251524.murk-touched.name"] = "Trübsinn"
	L["variety.251524.polka-dotted.description"] = "Große weiße Punkte auf Rosa, wie ein Festkleid. Er weiß es."
	L["variety.251524.polka-dotted.name"] = "Tupfenkleid"
	L["variety.251524.rainbow.description"] = "Jede Farbe in Streifen, als hätte ein Kind mit einem vollen Malkasten gemalt. Es glitzert."
	L["variety.251524.rainbow.name"] = "Regenbogen"
	L["variety.251524.swirled.description"] = "Rosa und Blau ineinander gewirbelt wie Zuckerguss. Macht Angler hungrig auf das Falsche."
	L["variety.251524.swirled.name"] = "Wirbel"
	L["variety.251524.whimsical.description"] = "Gold, mit wallenden blauen Flossen wie die Schals einer Tänzerin. Sieht aus, als hätte ihn jemand in bester Laune gemalt."
	L["variety.251524.whimsical.name"] = "Verspielt"
	L["variety.4603.all-gold.description"] = "Gelb von Schwanz bis Nase. Möwen folgen dem Boot meilenweit."
	L["variety.4603.all-gold.name"] = "Vollgold"
	L["variety.4603.classic.description"] = "Blaugrauer Rücken, gelber Schwanz, verstreute dunkle Flecken. So, wie jeder Küstenkoch ihn erwartet."
	L["variety.4603.classic.name"] = "Klassisch"
	L["variety.4603.dusky.description"] = "Dunkel aus tiefem Wasser, das Gelb zu altem Messing verblasst."
	L["variety.4603.dusky.name"] = "Düster"
	L["variety.4603.ghost.description"] = "Fast weiß, mit einem schwachen gelben Hauch am Schwanz. Sieht selbst außerhalb des Wassers aus wie unter Wasser."
	L["variety.4603.ghost.name"] = "Geist"
	L["variety.4603.gold-striped.description"] = "Eine gelbe Linie läuft von der Nase bis zum Schwanz, als hätte ihn jemand unterstrichen."
	L["variety.4603.gold-striped.name"] = "Goldstreif"
	L["variety.4603.greenback.description"] = "Am Rücken grüner, von krautigen Küsten. Der Schwanz bleibt stolz gelb."
	L["variety.4603.greenback.name"] = "Grünrücken"
	L["variety.4603.leopard.description"] = "Die Flecken wurden gierig und wuchsen zusammen. Hübsch, auf gedrängte Art."
	L["variety.4603.leopard.name"] = "Leopard"
	L["variety.4603.silverside.description"] = "Die Flanken hinab mehr Spiegel als Fisch. Die Flecken wenige und scheu."
	L["variety.4603.silverside.name"] = "Silberflanke"
	L["variety.4603.sunset-tailed.description"] = "Der Schwanz brennt orange statt gelb. Noch stolzer auf sich, falls das möglich ist."
	L["variety.4603.sunset-tailed.name"] = "Abendrotschwanz"
	L["variety.4603.tidecaller.description"] = "Feines blaues Netzmuster leuchtet entlang der Flanken. Alte Seeleute sagen, die Flut kippt, wenn einer an Land gezogen wird."
	L["variety.4603.tidecaller.name"] = "Gezeitenrufer"
	L["variety.6289.blackjaw.description"] = "Der Kiefer ist bis zu den Kiemen tintendunkel. Er hat Meinungen und teilt sie."
	L["variety.6289.blackjaw.name"] = "Schwarzmaul"
	L["variety.6289.brindle.description"] = "Gestreift wie das Fell eines Jagdhunds. Manche Angler schwören, er knurrt."
	L["variety.6289.brindle.name"] = "Gestromt"
	L["variety.6289.golden.description"] = "Ein goldener Schnapper aus einem braunen Teich. Der Teich scheint so überrascht wie alle anderen."
	L["variety.6289.golden.name"] = "Golden"
	L["variety.6289.lantern-eyed.description"] = "Augen, die das Licht fangen wie eine Lampe im Fenster. In der Dämmerung leichter zu finden."
	L["variety.6289.lantern-eyed.name"] = "Laternenauge"
	L["variety.6289.mudbank.description"] = "Oben braun, unten hellbraun, Kiefer voran. Der Schnapper, den scheinbar jeder Teich der Welt hat."
	L["variety.6289.mudbank.name"] = "Schlammbank"
	L["variety.6289.old-bootbiter.description"] = "Hakennarben, eine zerrissene Flosse und ein Ausdruck völliger Zuversicht. Jeder Teich hat einen."
	L["variety.6289.old-bootbiter.name"] = "Alter Stiefelbeißer"
	L["variety.6289.pale.description"] = "Milchbleich, rosa an den Flossen. Zu hübsch für den Kiefer, den er trägt."
	L["variety.6289.pale.name"] = "Bleich"
	L["variety.6289.red-clay.description"] = "Rostrot, von Flussufern aus rotem Lehm. Schmeckt gleich, sieht heißer aus."
	L["variety.6289.red-clay.name"] = "Rotlehm"
	L["variety.6289.reedbed.description"] = "Schwache grüne Streifen, vom Verstecken im Schilf. Beißt trotzdem zuerst."
	L["variety.6289.reedbed.name"] = "Röhricht"
	L["variety.6289.speckled.description"] = "Überall sommersprossig, wie ein Knecht nach der Ernte."
	L["variety.6289.speckled.name"] = "Gesprenkelt"
	L["variety.6291.blue-striped.description"] = "Ein ordentlicher blauer Streifen an jeder Seite, als wollte er amtlich aussehen."
	L["variety.6291.blue-striped.name"] = "Blaustreif"
	L["variety.6291.dotted.description"] = "Eine Reihe kleiner Tupfen entlang der Flanke, ordentlich wie eine Naht."
	L["variety.6291.dotted.name"] = "Getupft"
	L["variety.6291.glass.description"] = "Man sieht sein Rückgrat. Er sieht deins vermutlich auch."
	L["variety.6291.glass.name"] = "Glas"
	L["variety.6291.golden.description"] = "Eine Goldmünze mit Flossen. Kinder wollen ihn behalten. Angler auch."
	L["variety.6291.golden.name"] = "Golden"
	L["variety.6291.greenback.description"] = "Grün über den Rücken, aus flachem, krautigem Wasser. Doppelt so schwer zu entdecken."
	L["variety.6291.greenback.name"] = "Grünrücken"
	L["variety.6291.inkfin.description"] = "Dunkel wie eine Federspitze. Schwimmt mit den hellen und täuscht niemanden."
	L["variety.6291.inkfin.name"] = "Tintenflosse"
	L["variety.6291.rainbow.description"] = "Wirft beim Wenden Farben wie eine Seifenblase. An Land wird er grau."
	L["variety.6291.rainbow.name"] = "Regenbogen"
	L["variety.6291.redfin.description"] = "Flossen wie in Rot getaucht. Gibt im Schwarm an, selten allein."
	L["variety.6291.redfin.name"] = "Rotflosse"
	L["variety.6291.silver.description"] = "Schlichtes Silber, das zu Hunderten im Flachwasser blitzt. Der erste Fisch in sehr vielen Büchern."
	L["variety.6291.silver.name"] = "Silbern"
	L["variety.6291.starlit.description"] = "Winzige blasse Punkte leuchten auf seinem Rücken wie eine klare Nacht. Bemerkenswert für etwas so Kleines."
	L["variety.6291.starlit.name"] = "Sternenlicht"
	L["variety.6299.ashen.description"] = "Grau bis auf die Knochen, als wäre er durch Asche geschwommen. Selbst die Fliegen halten Abstand."
	L["variety.6299.ashen.name"] = "Aschgrau"
	L["variety.6299.bilious.description"] = "Gelbgrün wie ein übler Morgen. Nur mit Handschuhen anfassen."
	L["variety.6299.bilious.name"] = "Gallig"
	L["variety.6299.blighted.description"] = "Schwache grüne Adern leuchten unter den Schuppen. Manche Gewässer erinnern sich, was in sie geflossen ist."
	L["variety.6299.blighted.name"] = "Verseucht"
	L["variety.6299.blotchy.description"] = "Bedeckt mit traurigen braunen Flecken. Niemand fragt, woher."
	L["variety.6299.blotchy.name"] = "Fleckig"
	L["variety.6299.bony.description"] = "Mehr Rippen als Fisch. Er hat sich Mühe gegeben."
	L["variety.6299.bony.name"] = "Knochig"
	L["variety.6299.bruised.description"] = "Stellenweise lila und blau, als hätte er einen Kampf mit der Strömung verloren."
	L["variety.6299.bruised.name"] = "Zerschunden"
	L["variety.6299.greenish.description"] = "Grüne Flecken, die nicht da sein sollten. Der Geruch kommt vor dem Fisch an."
	L["variety.6299.greenish.name"] = "Grünlich"
	L["variety.6299.greyish.description"] = "Grau, schlaff und leicht zerknirscht. Sieht schlecht aus und riecht schlimmer."
	L["variety.6299.greyish.name"] = "Gräulich"
	L["variety.6299.recovered.description"] = "Gesünder als die anderen. Und doch unverkennbar einer von ihnen."
	L["variety.6299.recovered.name"] = "Genesen"
	L["variety.6299.wheezing.description"] = "Die Kiemen flattern so, dass es fast wie ein Seufzer klingt. Er weiß es."
	L["variety.6299.wheezing.name"] = "Keuchend"
	L["variety.6303.blueback.description"] = "Blauer, von der offenen See. Lässt sich genauso gut braten."
	L["variety.6303.blueback.name"] = "Blaurücken"
	L["variety.6303.bronze.description"] = "Bronze am Rücken wie eine alte Münze. Seltsam für eine Makrele. Ihr ist das egal."
	L["variety.6303.bronze.name"] = "Bronze"
	L["variety.6303.emerald.description"] = "Grün wie Tang, mit einem Schimmer, der binnen einer Stunde vergeht."
	L["variety.6303.emerald.name"] = "Smaragd"
	L["variety.6303.golden.description"] = "Goldene Streifen auf Gold. Sieht teuer aus. Brät wie eine Makrele."
	L["variety.6303.golden.name"] = "Golden"
	L["variety.6303.pearl.description"] = "Weiß wie eine Muschel, die Streifen nur ein Schatten ihrer selbst. Wunderschön, und immer noch glitschig."
	L["variety.6303.pearl.name"] = "Perle"
	L["variety.6303.plainback.description"] = "Gar keine Streifen. Rutscht ohne sie anscheinend schneller durch die Hände."
	L["variety.6303.plainback.name"] = "Glattrücken"
	L["variety.6303.sea-witch.description"] = "Streifen, die im Dunkeln meergrün leuchten. Seeleute werfen sie zurück. Dann bereuen sie es."
	L["variety.6303.sea-witch.name"] = "Meerhexe"
	L["variety.6303.shallow-water.description"] = "Blasser, aus sandigen Buchten nahe am Ufer. Glitscht trotzdem."
	L["variety.6303.shallow-water.name"] = "Flachwasser"
	L["variety.6303.spotted.description"] = "Punkte, wo Streifen sein sollten. Makrelen nehmen es mit den Regeln nicht so genau."
	L["variety.6303.spotted.name"] = "Gefleckt"
	L["variety.6303.tiger-backed.description"] = "Wellige dunkle Streifen auf blaugrünem Rücken, wie erstarrte Wellen."
	L["variety.6303.tiger-backed.name"] = "Tigerrücken"
	L["variety.6308.albino.description"] = "Weiß mit rosa Augen. Hat offensichtlich nie die Sonne gesehen und hat es auch nicht vor."
	L["variety.6308.albino.name"] = "Albino"
	L["variety.6308.black-barbel.description"] = "Tintenschwarz von Bartel bis Schwanz. Schluckt das Licht und den größten Teil des Köders."
	L["variety.6308.black-barbel.name"] = "Schwarzbartel"
	L["variety.6308.calico.description"] = "Orange, weiß und schwarz gefleckt wie eine Scheunenkatze. Genauso unbeeindruckt."
	L["variety.6308.calico.name"] = "Dreifarbig"
	L["variety.6308.long-whiskered.description"] = "Barteln doppelt so lang wie üblich. Sieht weise aus. Ist es nicht."
	L["variety.6308.long-whiskered.name"] = "Langbartel"
	L["variety.6308.marbled.description"] = "Gesprenkelt wie ein Flussbett, und genau dort verbringt er seine Zeit."
	L["variety.6308.marbled.name"] = "Marmoriert"
	L["variety.6308.mudback.description"] = "Oben schlammbraun, unten cremefarben, überall Barteln. Der Wels, den scheinbar jeder Fluss hält."
	L["variety.6308.mudback.name"] = "Schlammrücken"
	L["variety.6308.riverbed-king.description"] = "Barteln dick wie Seile und ein Maul wie eine Kellertür. Der Fluss füttert ihn seit Jahren."
	L["variety.6308.riverbed-king.name"] = "Flussbettkönig"
	L["variety.6308.slate.description"] = "Blaugrau wie Flussgestein. Genauso stur."
	L["variety.6308.slate.name"] = "Schiefer"
	L["variety.6308.spotted.description"] = "Dunkle Flecken entlang der Flanken, wie bei einem jungen Gabelwels."
	L["variety.6308.spotted.name"] = "Gefleckt"
	L["variety.6308.yellowbelly.description"] = "Ein gelber Bauch und keine Scham darüber. Kämpft trotzdem."
	L["variety.6308.yellowbelly.name"] = "Gelbbauch"
	L["variety.6317.ale-barred.description"] = "Bernsteinfarbene Streifen wie ein gut gezapftes Bier. Zwerge geben diesen liebevolle Namen."
	L["variety.6317.ale-barred.name"] = "Bierstreif"
	L["variety.6317.blackwater.description"] = "Schwarz wie der Grund eines Bergwerksschachts. Die Zähne sind weiß."
	L["variety.6317.blackwater.name"] = "Schwarzwasser"
	L["variety.6317.dam-breaker.description"] = "Zähne wie Meißel und ein Kiefer voller alter Splitter. Geschichten am Bergsee beginnen und enden mit ihm."
	L["variety.6317.dam-breaker.name"] = "Dammbrecher"
	L["variety.6317.ironjaw.description"] = "Der Kiefer dunkel wie altes Eisen und fast so hart. Handschuhe empfohlen."
	L["variety.6317.ironjaw.name"] = "Eisenkiefer"
	L["variety.6317.peat-stained.description"] = "Braun von torfigem Wasser. Schmeckt leicht nach Rauch."
	L["variety.6317.peat-stained.name"] = "Torfbraun"
	L["variety.6317.redbelly.description"] = "Ein Bauch rot wie eine Esse. Die Zähne sind dieselben."
	L["variety.6317.redbelly.name"] = "Rotbauch"
	L["variety.6317.ruby.description"] = "Ganz rot, wie ein Edelstein im Licht einer Grubenlampe. Irgendwer versucht immer, ihn zu verkaufen."
	L["variety.6317.ruby.name"] = "Rubin"
	L["variety.6317.silverflank.description"] = "Hell silberne Flanken mit glitzernden Schuppen. Trotzdem nur Zähne."
	L["variety.6317.silverflank.name"] = "Silberflanke"
	L["variety.6317.slate-backed.description"] = "Grauer Rücken, roter Bauch, Zähne. Benannt danach, wie er sich benimmt, wenn man ihn hält."
	L["variety.6317.slate-backed.name"] = "Schieferrücken"
	L["variety.6317.snowmelt.description"] = "Blass aus der kältesten Ecke des Bergsees. Beißt genauso hart."
	L["variety.6317.snowmelt.name"] = "Schneeschmelze"
	L["variety.6358.black-gummed.description"] = "Schwarzes Zahnfleisch, gefleckter Rücken, ein öliger Glanz. Alchemisten wollen das Öl."
	L["variety.6358.black-gummed.name"] = "Schwarzgaumen"
	L["variety.6358.bright-silver.description"] = "Frisch aus offenem Wasser und hell wie eine Klinge. Das Öl ist trotzdem da."
	L["variety.6358.bright-silver.name"] = "Hellsilber"
	L["variety.6358.greenback.description"] = "Oben grüner, von Tangküsten. Genauso ölig."
	L["variety.6358.greenback.name"] = "Grünrücken"
	L["variety.6358.hooknose.description"] = "Ein Hakenkiefer von seiner Laichwanderung. Sieht stets beleidigt aus."
	L["variety.6358.hooknose.name"] = "Hakennase"
	L["variety.6358.lampblack.description"] = "Goldenes Öl sickert entlang seiner Schuppen und leuchtet schwach. Lampenmacher würden alles zahlen. Meist tun sie es."
	L["variety.6358.lampblack.name"] = "Lampenruß"
	L["variety.6358.pearl.description"] = "Weiß, mit perligem Glanz von all dem Öl. Hübscher als sein Ruf."
	L["variety.6358.pearl.name"] = "Perle"
	L["variety.6358.rainbow-slicked.description"] = "Das Öl zeigt im Sonnenlicht jede Farbe. Hübscher, als etwas so Schmieriges verdient."
	L["variety.6358.rainbow-slicked.name"] = "Regenbogenglanz"
	L["variety.6358.redflank.description"] = "Zum Laichen an den Flanken rot geworden. Öliger denn je."
	L["variety.6358.redflank.name"] = "Rotflanke"
	L["variety.6358.spotless.description"] = "Kein einziger Fleck. Das Öl übernimmt das Verzieren."
	L["variety.6358.spotless.name"] = "Makellos"
	L["variety.6358.tar-black.description"] = "Schwarz vom Maul bis zum Schwanz und glatt wie Teer. Hinterlässt auf allem, was er berührt, Spuren."
	L["variety.6358.tar-black.name"] = "Teerschwarz"
	L["variety.6359.charred.description"] = "Schwarz wie ein verbranntes Scheit, die Flossen glühen noch rot. Sieht gar aus. Ist es nicht."
	L["variety.6359.charred.name"] = "Verkohlt"
	L["variety.6359.coral.description"] = "Rosiger, aus Riffwasser. Etwas kühler in der Hand."
	L["variety.6359.coral.name"] = "Koralle"
	L["variety.6359.deepwater.description"] = "Dunkelrot aus tiefem Wasser. Hält die Wärme länger."
	L["variety.6359.deepwater.name"] = "Tiefwasser"
	L["variety.6359.ember-spotted.description"] = "Dunkle Flecken wie Kohlestückchen auf Rot. Riecht beim Landen leicht nach Rauch."
	L["variety.6359.ember-spotted.name"] = "Glutfleck"
	L["variety.6359.flame-finned.description"] = "Roter Körper, Flossen wie Flammen. Die Farbe, die sich die meisten Angler beim Namen vorstellen."
	L["variety.6359.flame-finned.name"] = "Flammenflosse"
	L["variety.6359.flame-striped.description"] = "Gelbe Linien laufen an ihm hinab wie Flammen eine Wand hinauf."
	L["variety.6359.flame-striped.name"] = "Flammenstreif"
	L["variety.6359.goldfin.description"] = "Goldene statt roter Flossen. Immer noch warm."
	L["variety.6359.goldfin.name"] = "Goldflosse"
	L["variety.6359.phoenix-fin.description"] = "Die Flossen brennen golden, und der Körper glüht wie eine Esse. Das Wasser dampft um ihn, wenn er landet."
	L["variety.6359.phoenix-fin.name"] = "Phönixflosse"
	L["variety.6359.smouldering.description"] = "Dunkel wie ein abgedecktes Feuer, rot an den Rändern. Zu warm, um ihn lange zu halten."
	L["variety.6359.smouldering.name"] = "Schwelend"
	L["variety.6359.white-flame.description"] = "Weiß, mit Flossen im Rosa glühender Kohle. Die Hitze ist echt."
	L["variety.6359.white-flame.name"] = "Weißflamme"
	L["variety.6361.aurora.description"] = "Farben laufen in Wellen über ihn, von Grün bis Violett, und verblassen nie. Niemand kann es erklären."
	L["variety.6361.aurora.name"] = "Polarlicht"
	L["variety.6361.barred.description"] = "Blasse Streifen die Flanken hinab, wie Thunfische sie zeigen, wenn sie gierig fressen."
	L["variety.6361.barred.name"] = "Quergestreift"
	L["variety.6361.deep-blue.description"] = "Dunkler, von weit draußen. Die Flossen behalten ihre Farben etwas länger."
	L["variety.6361.deep-blue.name"] = "Tiefblau"
	L["variety.6361.longfin.description"] = "Brustflossen so lang wie ein Unterarm. Schwimmt, als gehöre ihm das Meer."
	L["variety.6361.longfin.name"] = "Langflosse"
	L["variety.6361.many-hued.description"] = "Stahlblauer Rücken, silberner Bauch, Flossen in allen Farben. Sie verblassen binnen einer Stunde, also schau schnell."
	L["variety.6361.many-hued.name"] = "Vielfarbig"
	L["variety.6361.prism.description"] = "Weiß wie Gischt, jeder Streifen eine andere Farbe. Hält sie einen ganzen Tag."
	L["variety.6361.prism.name"] = "Prisma"
	L["variety.6361.silverflank.description"] = "Mehr Silber als Blau. Der Regenbogen lebt allein in den Flossen."
	L["variety.6361.silverflank.name"] = "Silberflanke"
	L["variety.6361.stormback.description"] = "Grau wie Gewittertürme, die Flossen zu Zinn verblasst. Beißt am besten kurz vor dem Regen."
	L["variety.6361.stormback.name"] = "Sturmrücken"
	L["variety.6361.sunset-finned.description"] = "Flossen in Orange und Rosé, wie ein Himmel am Ende eines guten Angeltags."
	L["variety.6361.sunset-finned.name"] = "Abendrotflosse"
	L["variety.6361.violet.description"] = "Ein violetter Schimmer auf dem Rücken. Nach dem Landen verblassen die Farben zu schmollendem Grau."
	L["variety.6361.violet.name"] = "Violett"
	L["variety.6362.barnacled.description"] = "Seepocken auf dem Kopf wie auf einem alten Rumpf. Macht das offensichtlich schon lange."
	L["variety.6362.barnacled.name"] = "Seepocken"
	L["variety.6362.golden.description"] = "Goldene Sprenkel auf Gold. Sieht aus wie eine Statue, die jemand nicht fertig gemacht hat."
	L["variety.6362.golden.name"] = "Golden"
	L["variety.6362.granite.description"] = "Schwarz-weiß gesprenkelt wie ein Mühlstein. Wiegt, als wäre er einer."
	L["variety.6362.granite.name"] = "Granit"
	L["variety.6362.harbour-grey.description"] = "Grau vom Hafenwasser. Gekocht genauso süß."
	L["variety.6362.harbour-grey.name"] = "Hafengrau"
	L["variety.6362.kelp-green.description"] = "Grünbraun aus Tangwäldern. Zieht stärker, als er aussieht."
	L["variety.6362.kelp-green.name"] = "Tanggrün"
	L["variety.6362.leopard.description"] = "Kräftige dunkle Flecken auf sandfarbenem Körper. Stur, selbst für einen Kabeljau."
	L["variety.6362.leopard.name"] = "Leopard"
	L["variety.6362.red-rock.description"] = "Rostrot, von Küsten aus rotem Fels. Einheimische halten ihn für einen anderen Fisch. Ist er nicht."
	L["variety.6362.red-rock.name"] = "Rotfels"
	L["variety.6362.rock-mottled.description"] = "Braun gesprenkelt wie die Felsen, zwischen denen er sich versteckt, mit einer hellen Linie an jeder Flanke."
	L["variety.6362.rock-mottled.name"] = "Felsmuster"
	L["variety.6362.sandy.description"] = "Blass wie ein Strand, fein gesprenkelt. Macht sich gut auf dem Teller."
	L["variety.6362.sandy.name"] = "Sandig"
	L["variety.6362.stoneheart.description"] = "Schuppen wie Schiefer, dazwischen ein schwaches Leuchten. Zu finden, wo die Klippen auf tiefes Wasser treffen, und nirgends sonst."
	L["variety.6362.stoneheart.name"] = "Steinherz"
	L["variety.6458.black-gold.description"] = "So dick überzogen, dass alles glänzt wie ein gewienerter Stiefel. Prospektoren werfen einen Blick darauf und fangen an zu graben."
	L["variety.6458.black-gold.name"] = "Schwarzes Gold"
	L["variety.6458.half-clean.description"] = "Das Öl hat nur die Hälfte erwischt. Die andere Hälfte wirkt still erleichtert."
	L["variety.6458.half-clean.name"] = "Halb sauber"
	L["variety.6458.muddy.description"] = "Mehr Schlamm als Öl. Eine Verbesserung, gewissermaßen."
	L["variety.6458.muddy.name"] = "Schlammig"
	L["variety.6458.rainbow-slick.description"] = "Das Öl wirft in der Sonne Regenbögen. Ein hübscher Anblick, und ein schlechtes Zeichen."
	L["variety.6458.rainbow-slick.name"] = "Regenbogenfilm"
	L["variety.6458.rust-streaked.description"] = "Rostschlieren von altem Maschinenabfluss. Beinahe ein Fisch."
	L["variety.6458.rust-streaked.name"] = "Roststreifig"
	L["variety.6458.slicked.description"] = "Ein kleiner Fisch unter einem schwarzen Ölmantel. Irgendwo flussaufwärts ist jemand sehr beschäftigt."
	L["variety.6458.slicked.name"] = "Ölverschmiert"
	L["variety.6458.somehow-clean.description"] = "Sauber, hell, gesund. Muss von woanders hergeschwommen sein."
	L["variety.6458.somehow-clean.name"] = "Irgendwie sauber"
	L["variety.6458.still-burning.description"] = "Das Öl auf dem Rücken glimmt noch, und nichts löscht es. Lieber nicht drinnen braten."
	L["variety.6458.still-burning.name"] = "Brennt noch"
	L["variety.6458.sulphur-stained.description"] = "Gelb von etwas Schlimmerem als Öl. Riecht auch so."
	L["variety.6458.sulphur-stained.name"] = "Schwefelfleckig"
	L["variety.6458.tarred.description"] = "Dicker schwarzer Teer in Flecken. Klebt an der Schnur und am Angler."
	L["variety.6458.tarred.name"] = "Geteert"
	L["variety.6522.crimson.description"] = "Rot, wo er grün sein sollte. Die Geschichten über die Stunde nach dem Verzehr werden immer schlimmer."
	L["variety.6522.crimson.name"] = "Karmesin"
	L["variety.6522.dreamers-spawn.description"] = "Grünes Licht pulsiert unter den Schuppen, langsam wie Atem im Schlaf. Der Albtraum der Höhlen hat hier Spuren hinterlassen."
	L["variety.6522.dreamers-spawn.name"] = "Brut des Träumers"
	L["variety.6522.glowgill.description"] = "Kiemen, die schwach grün glühen. Wirkt wie eine Warnung, und das ist es auch."
	L["variety.6522.glowgill.name"] = "Glühkieme"
	L["variety.6522.lizard-scaled.description"] = "Schuppen wie die Haut eines Raptors. Halb Fisch, halb etwas mit Meinungen."
	L["variety.6522.lizard-scaled.name"] = "Echsenschuppe"
	L["variety.6522.many-eyed.description"] = "Augenflecken die Flanken hinunter. Mindestens zwei davon blinzeln."
	L["variety.6522.many-eyed.name"] = "Vieläugig"
	L["variety.6522.misshapen.description"] = "Grün, knotig und an mehreren Stellen zugleich falsch. Verzehr auf eigene Gefahr."
	L["variety.6522.misshapen.name"] = "Missgestalt"
	L["variety.6522.pale-nightmare.description"] = "Geisterbleich, die Innereien schwach sichtbar. Wirkt wie ein böser Traum am helllichten Mittag."
	L["variety.6522.pale-nightmare.name"] = "Bleicher Albtraum"
	L["variety.6522.purple-finned.description"] = "Flossen in Blutergusslila. Niemand ist sich einig, ob das besser oder schlimmer ist."
	L["variety.6522.purple-finned.name"] = "Purpurflosse"
	L["variety.6522.spined.description"] = "Ein Stachelkamm den Rücken entlang, der gestern noch nicht da war."
	L["variety.6522.spined.name"] = "Stachelrücken"
	L["variety.6522.two-tailed.description"] = "Zwei Schwänze, und er schwimmt, als stritte er mit sich, welchen er nehmen soll."
	L["variety.6522.two-tailed.name"] = "Zweischwanz"
	L["variety.8365.bright-headed.description"] = "Olivfarbener Leib, gesprenkelte Flanken, ein Kopf, der glänzt wie poliertes Metall. Die übliche Forelle warmer Flüsse."
	L["variety.8365.bright-headed.name"] = "Glanzkopf"
	L["variety.8365.brook-spotted.description"] = "Helle Tupfen auf Oliv, aus kalten, schnellen Bächen."
	L["variety.8365.brook-spotted.name"] = "Bachgetupft"
	L["variety.8365.golden.description"] = "Ganz golden, wie die seltenen Forellen hoher Bergseen."
	L["variety.8365.golden.name"] = "Golden"
	L["variety.8365.goldhead.description"] = "Gold, wo der Glanz silbern sein sollte. Der Schmied fragt zweimal nach."
	L["variety.8365.goldhead.name"] = "Goldkopf"
	L["variety.8365.ironhead.description"] = "Ganz dunkel, der Kopf wie Gusseisen. Genauso schwer zu garen."
	L["variety.8365.ironhead.name"] = "Eisenkopf"
	L["variety.8365.parr-marked.description"] = "Flecken wie Daumenabdrücke die Flanken hinunter, wie junge Forellen sie tragen. Spät erwachsen geworden."
	L["variety.8365.parr-marked.name"] = "Jugendzeichnung"
	L["variety.8365.quicksilver.description"] = "Silbern von der Nase bis zum Schwanz, mit blassblauem Schimmer. Endlich hat der Schmied einen Fall."
	L["variety.8365.quicksilver.name"] = "Quecksilber"
	L["variety.8365.rainbow-banded.description"] = "Ein rosa Band die Flanke entlang, wie es die Regenbogenforelle trägt."
	L["variety.8365.rainbow-banded.name"] = "Regenbogenband"
	L["variety.8365.red-spotted.description"] = "Rote Tupfen mit blauem Ring. Hübsch genug, dass ein Angler vor der Pfanne innehält."
	L["variety.8365.red-spotted.name"] = "Rottupfen"
	L["variety.8365.steelhead.description"] = "Graublau und glänzend, aus großen Gewässern. Zieht, als wäre es ernst gemeint."
	L["variety.8365.steelhead.name"] = "Stahlkopf"
end)
